import{_ as a,c as o,o as d,b0 as e}from"./chunks/framework.C5ev1SXp.js";const r="/scm-docs/assets/ota-system-architecture.Cs8hVAwr.svg",l="/scm-docs/assets/ota-upgrade-flow.DOiCcOI-.svg",i="/scm-docs/assets/ota-topic-map.DnWeKNz9.svg",f=JSON.parse('{"title":"LV001-OTA全景与设计目标","description":null,"frontmatter":{"title":"LV001-OTA全景与设计目标","date":"2026-10-14T22:30:41.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/online-upgrade/ota/126d628e38c13598570ff2c9","index":true,"tags":["OTA","固件升级"],"categories":["在线升级"],"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T22:30:41.857Z","fulluuid":"8570ff2c981f48339512ed2a6c2d3487","useduuid":"8570ff2c9"}},"headers":[],"relativePath":"sdoc/online-upgrade/ota/126d628e38c13598570ff2c9.md","filePath":"sdoc/70-在线升级/02-OTA/LV001-OTA全景与设计目标.md","lastUpdated":1792231946000}'),n={name:"sdoc/online-upgrade/ota/126d628e38c13598570ff2c9.md"};function s(c,t,h,p,u,m){return d(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="lv001-ota全景与设计目标" tabindex="-1">LV001-OTA全景与设计目标 <a class="header-anchor" href="#lv001-ota全景与设计目标" aria-label="Permalink to &quot;LV001-OTA全景与设计目标&quot;">​</a></h1><h2 id="一、-ota-是什么" tabindex="-1">一、 OTA 是什么 <a class="header-anchor" href="#一、-ota-是什么" aria-label="Permalink to &quot;一、 OTA 是什么&quot;">​</a></h2><h3 id="_1-ota-的定义" tabindex="-1">1. OTA 的定义 <a class="header-anchor" href="#_1-ota-的定义" aria-label="Permalink to &quot;1. OTA 的定义&quot;">​</a></h3><p>OTA（Over-The-Air，空中下载）升级，是指设备通过无线或有线网络远程获取新固件并完成自我更新，全程无需返厂、无需连接烧录器、无需人工拆机干预。它解决的核心问题是：<strong>设备卖出去之后，固件 Bug 修复、功能迭代、安全补丁如何触达成千上万的在网设备</strong>。</p><p>一次完整的 OTA 升级可以概括为一行流水线：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查更新 → 下载升级包 → 校验 → 写入存储 → 切换启动 → 确认生效 / 失败回滚</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-ota-与-iap、icp-的辨析" tabindex="-1">2. OTA 与 IAP、ICP 的辨析 <a class="header-anchor" href="#_2-ota-与-iap、icp-的辨析" aria-label="Permalink to &quot;2. OTA 与 IAP、ICP 的辨析&quot;">​</a></h3><p>嵌入式领域有三个容易混淆的烧录/升级术语，它们的区别在于&quot;谁来提供新固件、走什么通道&quot;：</p><table tabindex="0"><thead><tr><th>术语</th><th>全称</th><th>通道</th><th>固件来源</th><th>典型场景</th></tr></thead><tbody><tr><td>ICP</td><td>In-Circuit Programming</td><td>SWD / JTAG 调试口</td><td>烧录器</td><td>产线烧录、开发调试</td></tr><tr><td>IAP</td><td>In-Application Programming</td><td>任意通信口（UART / USB / CAN…）</td><td>上位机、调试助手</td><td>bootloader 在线烧录</td></tr><tr><td>OTA</td><td>Over-The-Air</td><td>网络（Wi-Fi / 4G / 以太网 / LoRa…）</td><td>远程服务器</td><td>量产设备远程升级</td></tr></tbody></table><p>三者的关系可以这样理解：</p><ul><li>ICP 是&quot;外科手术&quot;，需要接触硬件调试口，设备必须拿到手边</li><li>IAP 是一种<strong>能力</strong>：应用程序在运行中自己擦写 Flash。OTA 的写入动作本质上就是 IAP</li><li>OTA 是一种<strong>业务</strong>：在 IAP 能力之上，叠加了版本管理、远程分发、校验、回滚等一整套机制</li></ul><p>一句话：<strong>IAP 是让芯片能自己写自己，OTA 是让设备能从云端拿新固件再自己写自己</strong>。本专题讨论的正是后者这套完整业务。</p><h3 id="_3-ota-的适用对象" tabindex="-1">3. OTA 的适用对象 <a class="header-anchor" href="#_3-ota-的适用对象" aria-label="Permalink to &quot;3. OTA 的适用对象&quot;">​</a></h3><p>OTA 不是 Linux 设备的专利，从几 KB Flash 的单片机到车载域控制器都可以做 OTA，只是方案复杂度差异巨大：</p><ul><li>资源受限 MCU（如 STM32F103）：需要自己实现 Bootloader、选槽、回滚的全部机制，详见 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c3020dff592c66.html">LV022-MCU无BankSwap落地方案</a> 与 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c3115442925860.html">LV025-MCU有BankSwap落地方案</a></li><li>带 MMU、跑 Linux 的应用处理器（如 RK3568、i.MX6ULL）：U-Boot + 开源框架（SWUpdate / RAUC / Mender）已经把机制做成熟了，重点在方案选型与集成，详见 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c31f8fa1682294.html">LV028-Linux平台OTA方案</a></li></ul><h2 id="二、-ota-系统的角色与架构" tabindex="-1">二、 OTA 系统的角色与架构 <a class="header-anchor" href="#二、-ota-系统的角色与架构" aria-label="Permalink to &quot;二、 OTA 系统的角色与架构&quot;">​</a></h2><p>一套 OTA 系统由三个角色构成：<strong>服务器端</strong>负责生产与分发升级包，<strong>传输通道</strong>负责可靠送达，<strong>设备端</strong>负责接收、校验、安装与自我恢复。</p><p><img src="'+r+'" alt="OTA 升级系统角色架构"></p><h3 id="_1-服务器端" tabindex="-1">1. 服务器端 <a class="header-anchor" href="#_1-服务器端" aria-label="Permalink to &quot;1. 服务器端&quot;">​</a></h3><p>服务器端是整个 OTA 体系的&quot;大脑&quot;，职责包括：</p><ul><li>版本管理：维护固件仓库，记录每个版本适用的设备型号、硬件批次、区域</li><li>升级策略：决定&quot;谁该升、什么时候升&quot;——灰度发布、分组推送、强制升级</li><li>差分包生成：基于新旧版本镜像用 bsdiff 等算法预先生成差分包，减少设备下载流量</li></ul><p>服务器端不一定是云端平台，小型项目里一台 HTTP 文件服务器加一个版本描述 JSON 就足够了。服务器端的详细设计见 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c32e59ac3bff9f.html">LV031-发布与量产运维</a>。</p><h3 id="_2-传输通道" tabindex="-1">2. 传输通道 <a class="header-anchor" href="#_2-传输通道" aria-label="Permalink to &quot;2. 传输通道&quot;">​</a></h3><p>传输通道的唯一要求是<strong>可靠地把字节流送达设备</strong>，常见的有：</p><ul><li>HTTPS：最通用，自带 TLS 加密与证书体系，Linux 设备首选</li><li>MQTT：适合 IoT 平台，借发布/订阅通道推送升级通知，固件本身一般仍走 HTTP 拉取</li><li>私有协议：MCU 外挂通信模组（ESP8266、4G 模组）时，常见&quot;MCU 用 UART 逐块向模组要数据&quot;的私有分块协议</li></ul><p>除了这三类网络通道，OTA 还大量使用<strong>近场通道</strong>——UART（YMODEM）、USB DFU、CAN、BLE 等，多用于开发调试、产线与救砖，详见 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e54cc179798793274.html">LV013-升级通道协议</a>。</p><p>通道层不保证的内容（包是否完整、是否被篡改、是否适配本机）由设备端自己校验，这是&quot;不信任通道&quot;的基本安全原则，详见 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c231b7f3f87647.html">LV019-升级安全机制</a>。</p><h3 id="_3-设备端" tabindex="-1">3. 设备端 <a class="header-anchor" href="#_3-设备端" aria-label="Permalink to &quot;3. 设备端&quot;">​</a></h3><p>设备端内部又分为三层，职责严格分离：</p><ul><li>App（业务应用）：正常运行时负责查询更新、下载升级包、写入非活动槽、置升级标志。升级的主要工作其实发生在旧 App 还活着的时候</li><li>OTA 代理：App 内部（或独立任务/进程）负责下载、分块校验、写 Flash 的逻辑模块</li><li>Bootloader：设备上电的第一段代码，升级后负责校验新固件、决定启动哪个槽、失败时回滚。它是升级安全的<strong>最后防线</strong>，因此自身必须简单、稳定，通常不参与 OTA 更新</li></ul><p>【<strong>注意</strong>】</p><p>Bootloader 不参与自身升级是通用原则：一旦 Bootloader 被刷坏，设备失去一切自救能力，只能拆机用调试口恢复。</p><h2 id="三、-ota-通用升级流程" tabindex="-1">三、 OTA 通用升级流程 <a class="header-anchor" href="#三、-ota-通用升级流程" aria-label="Permalink to &quot;三、 OTA 通用升级流程&quot;">​</a></h2><p>无论 MCU 还是 Linux 平台，OTA 的流程骨架是一致的，差异只在每一步的实现手段。</p><p><img src="'+l+'" alt="OTA 通用升级流程"></p><h3 id="_1-发现新版本" tabindex="-1">1. 发现新版本 <a class="header-anchor" href="#_1-发现新版本" aria-label="Permalink to &quot;1. 发现新版本&quot;">​</a></h3><p>三种触发模式：</p><ul><li>手动触发：用户主动点&quot;检查更新&quot;。服务器压力最小，但版本收敛最慢，适合有屏幕、有人操作的设备</li><li>设备轮询：设备定期向服务器请求版本描述文件（JSON / 私有格式），与本地版本比对。实现简单，服务器无状态，是绝大多数方案的选择</li><li>服务器推送：服务器通过 MQTT 等长连接主动通知设备升级。实时性好，适合需要统一调度的大规模设备群</li></ul><p>发现新版本之后还有两个独立选择：要不要弹提示等用户确认、什么时候执行。它们与触发模式一起构成&quot;升级在用户侧怎么发生&quot;这个运营维度，三种选择的组合与取舍见 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c205c45e07232d.html">LV004-升级方案维度与选型</a> 第四节。</p><p>版本比对不能只看版本号大小，还要匹配设备型号、硬件版本、区域、灰度白名单，防止把 A 型号的固件推给 B 型号。</p><h3 id="_2-下载升级包" tabindex="-1">2. 下载升级包 <a class="header-anchor" href="#_2-下载升级包" aria-label="Permalink to &quot;2. 下载升级包&quot;">​</a></h3><p>下载阶段的核心诉求是<strong>抗网络抖动</strong>：</p><ul><li>断点续传：记录已下载偏移，网络中断后从断点继续，而不是从头再来</li><li>分块校验：边下载边按块校验（如每 4 KB 一个 CRC），尽早发现数据错误，避免整个包下完才发现损坏</li><li>写入位置：下载的固件必须写到<strong>非活动槽 / 暂存区</strong>，绝不能直接覆盖正在运行的系统</li></ul><h3 id="_3-校验升级包" tabindex="-1">3. 校验升级包 <a class="header-anchor" href="#_3-校验升级包" aria-label="Permalink to &quot;3. 校验升级包&quot;">​</a></h3><p>下载完成后、置位升级标志之前，必须完成两道校验：</p><ul><li>完整性校验：对整个镜像计算 SHA-256（或 CRC32），与包内元数据中的预期值比对</li><li>真实性校验：用设备内置的厂商公钥对升级包签名做验签，确认包确实来自厂商而非攻击者</li></ul><p>任何一道不通过，丢弃升级包并上报失败原因，设备继续运行旧固件，本次升级对用户无感。</p><h3 id="_4-请求切换" tabindex="-1">4. 请求切换 <a class="header-anchor" href="#_4-请求切换" aria-label="Permalink to &quot;4. 请求切换&quot;">​</a></h3><p>校验通过后，App 把&quot;请下次从 B 槽启动&quot;这个意图写入 Flash 中的<strong>启动参数区</strong>（boot control），然后主动重启。从这一刻起，决策权移交给 Bootloader。参数区的字段设计与读写时序是 OTA 可靠性的核心，详见 <a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c223596cdb0056.html">LV016-选槽与回滚机制</a>。</p><h3 id="_5-bootloader-引导与确认" tabindex="-1">5. Bootloader 引导与确认 <a class="header-anchor" href="#_5-bootloader-引导与确认" aria-label="Permalink to &quot;5. Bootloader 引导与确认&quot;">​</a></h3><p>重启后 Bootloader 读取参数区，发现有待试用的新固件：</p><p>（1）再次校验新槽镜像（不信任 App 之前的结论，独立复查）</p><p>（2）校验通过则引导新固件，并记录&quot;已尝试启动次数&quot;</p><p>（3）新固件启动后进行自检（关键外设、通信链路、看门狗喂养正常）</p><p>（4）自检通过 → 新固件自己写参数区&quot;确认转正&quot;（mark good），升级完成</p><p>（5）自检失败或反复重启超过次数上限 → Bootloader 切回旧槽，<strong>回滚</strong>到旧固件</p><p>这个&quot;试用—确认—超限回退&quot;的机制保证了：哪怕新固件有严重 Bug 导致系统无法正常工作，设备也能自己退回旧版本，不会变砖。</p><h2 id="四、-ota-的核心设计目标" tabindex="-1">四、 OTA 的核心设计目标 <a class="header-anchor" href="#四、-ota-的核心设计目标" aria-label="Permalink to &quot;四、 OTA 的核心设计目标&quot;">​</a></h2><p>设计任何一套 OTA 方案时，所有取舍都围绕下面四个目标展开，后文每一篇的机制分析也都会回到这四条上。</p><h3 id="_1-原子性" tabindex="-1">1. 原子性 <a class="header-anchor" href="#_1-原子性" aria-label="Permalink to &quot;1. 原子性&quot;">​</a></h3><p>升级的任意时刻掉电，设备都必须处于一个<strong>确定的状态</strong>：要么还是完整的旧系统，要么是完整的新系统，绝不能是&quot;刷了一半&quot;的中间态。原子性靠&quot;先写非活动区、校验通过后再原子地翻标志位&quot;来保证。</p><h3 id="_2-可回滚" tabindex="-1">2. 可回滚 <a class="header-anchor" href="#_2-可回滚" aria-label="Permalink to &quot;2. 可回滚&quot;">​</a></h3><p>新固件自身有缺陷（能启动但功能异常、或反复崩溃）时，设备必须能自动退回旧版本。回滚的前提是<strong>旧固件的副本在升级全程不被破坏</strong>——这正是 A/B 双槽方案相比单槽复制方案的本质优势。</p><h3 id="_3-安全性" tabindex="-1">3. 安全性 <a class="header-anchor" href="#_3-安全性" aria-label="Permalink to &quot;3. 安全性&quot;">​</a></h3><p>升级通道是攻击者刷入恶意固件的天然入口，必须设防：</p><ul><li>来源可信：数字签名 + 设备端公钥验签</li><li>传输可信：TLS 加密，防中间人篡改</li><li>版本可信：防回滚机制，禁止降级到已知有漏洞的旧版本</li></ul><h3 id="_4-资源可控" tabindex="-1">4. 资源可控 <a class="header-anchor" href="#_4-资源可控" aria-label="Permalink to &quot;4. 资源可控&quot;">​</a></h3><p>OTA 不能影响设备正常业务：下载在后台限速进行，写 Flash 避开业务高峰，重启切换尽量快。Linux 上 A/B 方案可以做到&quot;用户无感升级&quot;，MCU 上则通常需要接受一次短暂重启。</p><h2 id="五、-本专题的结构与阅读路径" tabindex="-1">五、 本专题的结构与阅读路径 <a class="header-anchor" href="#五、-本专题的结构与阅读路径" aria-label="Permalink to &quot;五、 本专题的结构与阅读路径&quot;">​</a></h2><p>本专题 11 篇按&quot;原理 → 机制 → 平台方案 → 工程实践&quot;四层组织，编号顺序即阅读顺序。四层之间是<strong>抽象递减、落地递增</strong>的关系：原理层建立共同语言，机制层讲平台无关的做法，平台层落到具体芯片，实践层处理发布与运维。</p><p><img src="'+i+'" alt="OTA 专题的四层结构"></p><h3 id="_1-各篇职责与权威主题" tabindex="-1">1. 各篇职责与权威主题 <a class="header-anchor" href="#_1-各篇职责与权威主题" aria-label="Permalink to &quot;1. 各篇职责与权威主题&quot;">​</a></h3><p>每个主题在全专题只有<strong>一个权威出处</strong>，其余篇章只给结论并跳转，不重复展开。下表第四列即该篇的权威主题——要找某个机制的完整设计与代码，直接查这一列。</p><table tabindex="0"><thead><tr><th>层</th><th>篇目</th><th>回答的问题</th><th>权威主题</th></tr></thead><tbody><tr><td>原理</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c13598570ff2c9.html">LV001-OTA全景与设计目标</a></td><td>OTA 是什么、系统由谁构成</td><td>角色架构、通用流程骨架、四个设计目标</td></tr><tr><td>原理</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c205c45e07232d.html">LV004-升级方案维度与选型</a></td><td>有哪些做法、怎么选</td><td>存储布局对比、XIP 与 RAM 运行、触发与安装时机、升级期间可用性根因、选型决策树</td></tr><tr><td>机制</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c2149747002def.html">LV007-升级包格式与传输机制</a></td><td>包长什么样、怎么可靠送达</td><td>包头格式、断点续传、分块校验、Flash 擦写约束</td></tr><tr><td>机制</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e54cc2c3f10bc0c22.html">LV010-差分算法对比与嵌入式移植</a></td><td>差分怎么真正落地</td><td>差分算法对比、嵌入式移植、压缩选型、差分与 A/B 组合、补丁生成策略</td></tr><tr><td>机制</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e54cc179798793274.html">LV013-升级通道协议</a></td><td>字节流走哪条线</td><td>UART / USB DFU / CAN UDS / BLE / 网络模组的协议实现、通道分层原则</td></tr><tr><td>机制</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c223596cdb0056.html">LV016-选槽与回滚机制</a></td><td>装完怎么保证还能启动</td><td>启动参数区、双副本掉电安全、选槽决策、回滚状态机、看门狗配合</td></tr><tr><td>机制</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c231b7f3f87647.html">LV019-升级安全机制</a></td><td>怎么防止被刷入假固件</td><td>签名验签、信任链、防回滚、包加密、密钥管理</td></tr><tr><td>平台</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c3020dff592c66.html">LV022-MCU无BankSwap落地方案</a></td><td>老 MCU 上怎么落地</td><td>STM32F103 分区规划、四种方案、Bootloader 完整工程、App 改造清单、开源 Bootloader 复用</td></tr><tr><td>平台</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c3115442925860.html">LV025-MCU有BankSwap落地方案</a></td><td>硬件能帮掉什么忙</td><td>Bank Swap 地址映射、STM32L4/L5 实现、各系列差异、i.MX RT</td></tr><tr><td>平台</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c31f8fa1682294.html">LV028-Linux平台OTA方案</a></td><td>Linux 上怎么用现成机制</td><td>U-Boot bootcount、eMMC / NAND 分区、SWUpdate / RAUC / Mender、dm-verity、FIT 签名</td></tr><tr><td>工程实践</td><td><a href="/scm-docs/sdoc/online-upgrade/ota/126d628e38c32e59ac3bff9f.html">LV031-发布与量产运维</a></td><td>怎么发布、怎么测、怎么运维</td><td>版本描述文件、发布流水线、灰度分批、异常注入测试、量产 FAQ</td></tr></tbody></table><h3 id="_2-阅读路径" tabindex="-1">2. 阅读路径 <a class="header-anchor" href="#_2-阅读路径" aria-label="Permalink to &quot;2. 阅读路径&quot;">​</a></h3><p>（1）<strong>只想搞懂原理</strong>：LV001 → LV004。两篇读完即可参与方案讨论，不必深入机制层。</p><p>（2）<strong>在 MCU 上落地</strong>：LV001 → LV004 → LV007 → LV013 → LV016 → LV019 → LV022 或 LV025。最后一步取决于芯片是否支持硬件 Bank Swap：不支持走 LV022，支持走 LV025。差分与流量敏感时再补 LV010。</p><p>（3）<strong>在 Linux 上落地</strong>：LV001 → LV004 → LV016 → LV019 → LV028 → LV031。机制层可跳过 LV007 与 LV013——Linux 的传输由框架与 HTTP 栈接管，不需要自己设计包格式与通道协议。</p><p>（4）<strong>排查线上升级故障</strong>：先看 LV031 的 FAQ 表定位失败阶段，再到 LV016 的异常场景推演对照掉电点行为，最后按失败阶段回到对应机制篇（下载 / 校验 → LV007，写槽 → LV022 或 LV028，启动 → LV016，验签 → LV019）。</p><h3 id="_3-本篇的定位" tabindex="-1">3. 本篇的定位 <a class="header-anchor" href="#_3-本篇的定位" aria-label="Permalink to &quot;3. 本篇的定位&quot;">​</a></h3><p>本篇是原理层的入口，只做三件事：说清 OTA 与 IAP / ICP 的区别（第一节）、给出&quot;服务器—通道—设备&quot;的角色架构（第二节）、走一遍平台无关的流程骨架（第三节）。第四节提出的原子性、可回滚、安全性、资源可控四个目标，是后续每一篇做取舍时的共同判据——机制层的每套设计，最终都要回答&quot;它满足了这四条中的哪几条、牺牲了什么&quot;。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',83)])])}const A=a(n,[["render",s]]);export{f as __pageData,A as default};
